import{_ as a,o as t,c as s,a2 as o}from"./chunks/framework.vLhlLNVn.js";const b=JSON.parse('{"title":"Flash by USB","description":"","frontmatter":{"order":7},"headers":[],"relativePath":"adapter/esphome/flashbinary.md","filePath":"adapter/esphome/flashbinary.md","lastUpdated":1794652328000}'),l={name:"adapter/esphome/flashbinary.md"};function i(r,e,n,p,h,d){return t(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="flash-by-usb" tabindex="-1">Flash by USB <a class="header-anchor" href="#flash-by-usb" aria-label="Permalink to &quot;Flash by USB&quot;">​</a></h1><p>Flashing an *.bin binary to an ESP-Chipset is quite simple, if you use the proper tools. There are several ways how to do it, personally recommend using the esptool flasher.</p><h2 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Official download and Instruction</p><p><a href="https://github.com/espressif/esptool" target="_blank" rel="noreferrer">espressif/esptool</a></p></div><h2 id="mac" tabindex="-1">Mac <a class="header-anchor" href="#mac" aria-label="Permalink to &quot;Mac&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Use brew to get the dependencies</p><p><a href="https://brew.sh" target="_blank" rel="noreferrer">Get and install Brew</a> Install python <code>brew install python</code><br> Install esptool <code>brew install esptool</code><br> See for more information <a href="https://docs.brew.sh/Homebrew-and-Python" target="_blank" rel="noreferrer">Homebrew documentation</a></p></div><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">esptool.exe is included in the ESPEasy package</p><p>Get it from <a href="https://github.com/letscontrolit/ESPEasy/files/5566286/esp32tool-initial-flashing.zip" target="_blank" rel="noreferrer">lets control it</a><br> An alternative quite good instruction can be found at <a href="https://cyberblogspot.com/how-to-install-esptool-on-windows-10/" target="_blank" rel="noreferrer">cyberblogspot</a></p></div><h2 id="flash-commands" tabindex="-1">Flash commands <a class="header-anchor" href="#flash-commands" aria-label="Permalink to &quot;Flash commands&quot;">​</a></h2><p>The esptool.py command flash memory of an ESP8266:</p><p><code>esptool.py --port [serial-port-of-ESP8266] write_flash -fm dio -fs detect 0x00000 &gt;nodemcu-firmware&lt;.bin</code></p><h2 id="esp32-bootloader" tabindex="-1">ESP32 bootloader <a class="header-anchor" href="#esp32-bootloader" aria-label="Permalink to &quot;ESP32 bootloader&quot;">​</a></h2><p>For ESP32 you need to erase the flash, load the binary AND bootloader!</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Ge the required files from <a href="https://github.com/letscontrolit/ESPEasy/files/5566286/esp32tool-initial-flashing.zip" target="_blank" rel="noreferrer">lets control it</a></p></div><ol><li>Erase the flash</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>esptool.py--chip esp32 --port COM8 --baud 256000 --before default_reset --after hard_reset erase_flash</span></span></code></pre></div><ol start="2"><li>Flash the binary</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>esptool.py --chip esp32 --port COM8 --baud 256000 --before default_reset --after hard_reset write_flash -z --flash_mode dio --flash_freq 80m --flash_size detect 0x10000 &gt;binaryName&lt;.bin</span></span></code></pre></div><ol start="3"><li>Flash bootloader and partitions</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>esptool.py --chip esp32 --port COM8 --baud 256000 --before default_reset --after hard_reset write_flash -z --flash_mode dio --flash_freq 80m --flash_size detect 0x8000 ./initial-images/partitions2.bin 0xe000 ./initial-images/boot_app0.bin 0x1000 ./initial-images/bootloader.bin</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Replace esptool.py with the proper executable, like esptool.exe (Windows) or esp32tool.py/exe when using <a href="https://github.com/letscontrolit/ESPEasy/files/5566286/esp32tool-initial-flashing.zip" target="_blank" rel="noreferrer">lets control it librarys</a></p></div>',21)])])}const f=a(l,[["render",i]]);export{b as __pageData,f as default};
